  const [, updateArgs] = useArgs();
  const onChangePage = (newPage: number) => {
    updateArgs({
      currentPage: newPage,
      disabled: true
    });
    action('onPageChange')(newPage);
    setTimeout(() => {
      updateArgs({
        disabled: false
      });
    }, 500);
  };
  return <Pagination {...args} onChangePage={onChangePage} />;
